<?php else:?><div class="details-panel"><p><?=$view==='register'?'First verify your email. You will choose your password using the private link sent to your inbox.':'Request a private password-reset link. Your current password will not change until you complete the reset.'?></p><form class="public-form" method="post"><?=csrf_field()?><div class="honeypot" aria-hidden="true"><label>Company website<input name="company_website" tabindex="-1" autocomplete="off"></label></div><?php if($view==='register'):?><label>Your name<input name="name" maxlength="120" autocomplete="name" required></label><?php endif;?><label>Email address<input type="email" name="email" maxlength="190" autocomplete="email" required></label><?php if($view==='register'):?><label class="public-checkbox"><input type="checkbox" name="account_consent" value="1" required><span>I agree to the use of my details to create and manage my customer account. This does not subscribe me to marketing email.</span></label><?php endif;?><button type="submit" class="button wide">Send secure email</button></form><p class="small muted">Email links may take a few minutes to arrive. Keep them private.</p></div><?php endif;?>
